-- ============================================================================
-- 20260906184017_properties
-- Phase 10: properties + buildings + flats + rooms + publish state machine.
--
-- Spec: housing-platform/04 §4.3.2 (table shapes + index list),
--       housing-platform/05 §5.4 (room state machine, optimistic version).
--
-- Hand-edited extensions (not auto-generated by `prisma migrate dev`):
--   1. properties_city_status_published_idx — composite for the
--      search-by-city-and-publication query (04 §4.3.2 index list).
--   2. properties_geo_idx — btree on (latitude, longitude) for the
--      "nearby fallback queries before index search" path noted in
--      §4.3.2; sufficient for v1 since geo search itself lands in
--      Phase 11.
--   3. rooms_status_available_idx — composite (status, available_from)
--      powers the published-room feed sorted by availability.
--   4. rooms_amenities_gin — GIN on amenities TEXT[] per §4.3.2.
--   5. The previous migration's unrelated drift (drop / re-add of
--      preferences_tenant *_gin indexes, `tenant_id` SET DEFAULT
--      no-ops, `_uniq` → `_key` renames) is DROPPED — those are
--      Prisma's metadata-detection noise, not real schema changes.
-- ============================================================================

-- ── Enums ────────────────────────────────────────────────────────────────
CREATE TYPE "PropertyStatus" AS ENUM ('DRAFT', 'PUBLISHED', 'TAKEN_DOWN');
CREATE TYPE "PropertyType"   AS ENUM ('BUILDING', 'VILLA', 'STANDALONE_FLAT');
CREATE TYPE "BuildingStatus" AS ENUM ('ACTIVE', 'ARCHIVED');
CREATE TYPE "FlatStatus"     AS ENUM ('ACTIVE', 'ARCHIVED');
CREATE TYPE "RoomType"       AS ENUM ('PRIVATE', 'SHARED', 'STUDIO', 'ENTIRE_FLAT');
CREATE TYPE "RoomStatus"     AS ENUM (
  'DRAFT', 'PUBLISHED', 'RESERVED', 'OCCUPIED',
  'MAINTENANCE_CHECK', 'MAINTENANCE', 'TAKEN_DOWN'
);

-- ── Tables ───────────────────────────────────────────────────────────────
CREATE TABLE "properties" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "owner_user_id" UUID NOT NULL,
    "title" TEXT NOT NULL,
    "description" TEXT,
    "address_line1" TEXT NOT NULL,
    "address_line2" TEXT,
    "city" TEXT NOT NULL,
    "area" TEXT,
    "postal_code" TEXT,
    "country_code" CHAR(2) NOT NULL,
    "latitude" DECIMAL(9,6),
    "longitude" DECIMAL(9,6),
    "property_type" "PropertyType" NOT NULL,
    "status" "PropertyStatus" NOT NULL DEFAULT 'DRAFT',
    "published_at" TIMESTAMPTZ(6),
    "version" INTEGER NOT NULL DEFAULT 0,
    "tenant_id" UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ(6),

    CONSTRAINT "properties_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "buildings" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "property_id" UUID NOT NULL,
    "name" TEXT NOT NULL,
    "floors" INTEGER,
    "status" "BuildingStatus" NOT NULL DEFAULT 'ACTIVE',
    "tenant_id" UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ(6),

    CONSTRAINT "buildings_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "flats" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "building_id" UUID NOT NULL,
    "floor" INTEGER,
    "door_number" TEXT,
    "status" "FlatStatus" NOT NULL DEFAULT 'ACTIVE',
    "tenant_id" UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ(6),

    CONSTRAINT "flats_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "rooms" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "property_id" UUID NOT NULL,
    "flat_id" UUID,
    "label" TEXT NOT NULL,
    "room_type" "RoomType" NOT NULL,
    "size_sqft" DECIMAL(8,2),
    "max_occupants" INTEGER NOT NULL DEFAULT 1,
    "base_rent_minor" BIGINT NOT NULL,
    "deposit_minor" BIGINT NOT NULL,
    "currency" CHAR(3) NOT NULL,
    "bills_included" BOOLEAN NOT NULL DEFAULT false,
    "amenities" TEXT[],
    "status" "RoomStatus" NOT NULL DEFAULT 'DRAFT',
    "available_from" DATE,
    "min_lease_months" INTEGER,
    "max_lease_months" INTEGER,
    "rules" TEXT,
    "version" INTEGER NOT NULL DEFAULT 0,
    "tenant_id" UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ(6),

    CONSTRAINT "rooms_pkey" PRIMARY KEY ("id")
);

-- ── Indexes (Prisma-tracked) ─────────────────────────────────────────────
CREATE INDEX "properties_owner_idx"  ON "properties"("owner_user_id");
CREATE INDEX "properties_status_idx" ON "properties"("status", "deleted_at");
CREATE INDEX "buildings_property_idx" ON "buildings"("property_id");
CREATE INDEX "flats_building_idx"    ON "flats"("building_id");
CREATE INDEX "rooms_property_idx"    ON "rooms"("property_id");
CREATE INDEX "rooms_flat_idx"        ON "rooms"("flat_id");
CREATE INDEX "rooms_status_idx"      ON "rooms"("status", "deleted_at");
CREATE INDEX "rooms_currency_idx"    ON "rooms"("currency");

-- ── Hand-edited indexes (04 §4.3.2 index list) ──────────────────────────
CREATE INDEX "properties_city_status_published_idx"
    ON "properties"("city", "status", "published_at");
CREATE INDEX "properties_geo_idx"
    ON "properties"("latitude", "longitude");
CREATE INDEX "rooms_status_available_idx"
    ON "rooms"("status", "available_from");
CREATE INDEX "rooms_amenities_gin"
    ON "rooms" USING GIN ("amenities");

-- ── Foreign keys ─────────────────────────────────────────────────────────
ALTER TABLE "properties"
    ADD CONSTRAINT "properties_owner_user_id_fkey"
    FOREIGN KEY ("owner_user_id") REFERENCES "users"("id")
    ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "buildings"
    ADD CONSTRAINT "buildings_property_id_fkey"
    FOREIGN KEY ("property_id") REFERENCES "properties"("id")
    ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "flats"
    ADD CONSTRAINT "flats_building_id_fkey"
    FOREIGN KEY ("building_id") REFERENCES "buildings"("id")
    ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "rooms"
    ADD CONSTRAINT "rooms_property_id_fkey"
    FOREIGN KEY ("property_id") REFERENCES "properties"("id")
    ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "rooms"
    ADD CONSTRAINT "rooms_flat_id_fkey"
    FOREIGN KEY ("flat_id") REFERENCES "flats"("id")
    ON DELETE SET NULL ON UPDATE CASCADE;
